sysauto_script.script:
/**
 * Self-heal routine for the already-installed SafeTrace demo data.
 *
 * Repairs whatever it finds, then deactivates its own scheduled job once there
 * is nothing left to repair, so it stops consuming scheduler cycles.
 */
;(function runDemoDataSelfHeal() {
    var JOB_NAME = 'BFD - Demo data self-heal'
    var repair

    try {
        repair = new bfd_DemoDataRepair().repairAll()
    } catch (e) {
        gs.error('[' + JOB_NAME + '] repair failed: ' + e)
        return
    }

    gs.info('[' + JOB_NAME + '] ' + repair.summary)

    var repairedThisRun = repair.total_numbered + repair.total_snapshots
    if (repairedThisRun > 0) {
        gs.info(
            '[' +
                JOB_NAME +
                '] repaired ' +
                repairedThisRun +
                ' record(s) this run; re-checking on the next cycle before standing down.'
        )
        return
    }

    // Nothing left to repair - switch the job off.
    var job = new GlideRecord('sysauto_script')
    job.addQuery('name', JOB_NAME)
    job.setLimit(1)
    job.query()
    if (job.next()) {
        job.setValue('active', false)
        if (job.update()) {
            gs.info(
                '[' +
                    JOB_NAME +
                    '] nothing left to repair - job deactivated. Re-activate it, use the Cases list ' +
                    'banner button, or run the fix script if demo data is ever reloaded.'
            )
        }
    }
})()
